#include "ntdll_user.h"
void smss_main(void){NtWriteConsole("smss: SentinelOS installer session manager\n");char name[]={'i','n','s','t','l','r','.','e','x','e',0};NTSTATUS status=NtCreateProcess(name);if(status<0){NtWriteConsole(status==-2?"smss: instlr.exe has an incompatible image or launch policy\n":"smss: unable to load instlr.exe\n");for(;;)(void)sy3(SYS_Yield,0,0,0);}NtWriteConsole("smss: installer started; session manager staying alive\n");for(;;)(void)sy3(SYS_Yield,0,0,0);}
